class CircularIterator:
    def __init__(self, items: list):
        if not items:
            raise ValueError('Cannot cycle empty collection')
        self.items = items
        self.idx = 0

    def __iter__(self):
        return self

    def __next__(self):
        val = self.items[self.idx]
        self.idx = (self.idx + 1) % len(self.items)
        return val
```

